/bin/bash -lc "node --input-type=module <<'EOF'
const origin = 'http://localhost:3000';
const books = JSON.parse(await (await import('node:fs/promises')).readFile('/tmp/reading-room-test-books.json', 'utf8'));
const id = books[0].id;
const detail = await fetch("'`${origin}/books/${id}`);
const detailHtml = await detail.text();
console.log('"'DETAIL', detail.status, ['The Secret Garden', 'Frances Hodgson Burnett', 'Remember the robin.', 'Copy link'].map(text => detailHtml.includes(text)));
const homeHtml = await (await fetch(origin)).text();
const formHtml = homeHtml.match(/<form action=\"\"["'^>]*>(.*?)<'"\\/form>/)?.[1];
if ("'!formHtml) throw new Error('"'Finish form missing');
const form = new FormData();
for (const match of formHtml.matchAll(/<input type=\"hidden\" name=\"(["'^"]+)"(?: value="([''^"]*)")?'"\\/>/g)) {
  form.append(match[1], (match[2] ?? '').replaceAll('&quot;', '\"').replaceAll('&amp;', '&'));
}
const response = await fetch(origin, { method: 'POST', body: form, redirect: 'manual' });
console.log('FINISH POST', response.status);
const saved = JSON.parse(await (await import('node:fs/promises')).readFile('/tmp/reading-room-test-books.json', 'utf8'));
console.log('SAVED STATUS', saved[0].status, Boolean(saved[0].finishedAt));
const refreshed = await (await fetch(origin)).text();
console.log('FINISHED SECTION', refreshed.includes('Finished books'), refreshed.includes('The Secret Garden'));
EOF"

